class FuzzReader : public heif::Context::Reader {
public:
  explicit FuzzReader(const std::string& d) : data(d), pos(0) {}
  int64_t get_position() const override { return static_cast<int64_t>(pos); }
  int read(void* out, size_t size) override {
    if (pos >= data.size()) return 0; // EOF
    size_t n = size;
    if (pos + n > data.size()) n = data.size() - pos;
    memcpy(out, data.data() + pos, n);
    pos += n;
    return static_cast<int>(n);
  }
  int seek(int64_t p) override {
    if (p < 0) return -1;
    if (static_cast<size_t>(p) > data.size()) { pos = data.size(); return -1; }
    pos = static_cast<size_t>(p);
    return 0;
  }
  heif_reader_grow_status wait_for_file_size(int64_t target_size) override {
    return (target_size <= static_cast<int64_t>(data.size()))
             ? heif_reader_grow_status_size_reached
             : heif_reader_grow_status_size_beyond_eof;
  }
private:
  std::string data;
  size_t pos;
};
