import os
import random
import struct
from typing import List

# Generator for filesystem paths used by the target fuzzer stubs.
# Stubs consume FUZZ_PARAM_FILENAME() to load plugins or read/write HEIF files.
# We will generate a mixture of:
# - Existing temporary directories (".", "..", current working directory variations)
# - Likely plugin-like filenames with common extensions and prefixes
# - Absolute and relative paths
# - Nested directories
# - Paths with Unicode and edge-case characters
# - Paths with and without extensions
# The buffer returned is a single path encoded in UTF-8 with a trailing NUL byte, suitable for
# C-string style consumers. Keeping total size <= 4096 bytes.

UNICODE_FRAGMENTS = [
    "πlug", "プラグイン", "插件", "плагин", "플러그인", "ملحق", "éncoder", "décodeur",
    "α", "β", "γ", "雪", "🌈", "مرحبا", "ñ", "ç"
]

SAFE_DIRS = [".", "..", os.getcwd()]

PLUGIN_PREFIXES = [
    "libheif-", "libavif-", "heif-", "avif-", "codec-", "plugin-", "enc-", "dec-"
]

PLUGIN_EXTS_POSIX = [".so", ".dylib"]
PLUGIN_EXTS_WIN = [".dll"]
GENERIC_FILE_EXTS = [".heic", ".heif", ".avif", ".bin", ".dat", ".img", ""]

EDGE_DIRS = [
    "plugins", "../plugins", "./plugins", "tmp", "/tmp", "var/tmp", "build/plugins",
]

EDGE_NAMES = [
    "README", "LICENSE", "Makefile", "config", "default", "heif.conf", "index", "0", "1"
]

SEP = os.sep


def _rand_choice(rng: random.Random, arr: List[str]) -> str:
    return arr[rng.randrange(len(arr))]


def _random_unicode_fragment(rng: random.Random) -> str:
    frag = _rand_choice(rng, UNICODE_FRAGMENTS)
    # Occasionally add combining marks or repeat
    if rng.random() < 0.3:
        frag += "\u0301"  # combining acute
    if rng.random() < 0.2:
        frag = frag * rng.randint(1, 2)
    return frag


def _rand_plugin_basename(rng: random.Random) -> str:
    prefix = _rand_choice(rng, PLUGIN_PREFIXES)
    core = _rand_choice(rng, [
        "hevc", "av1", "avif", "jpeg", "j2k", "vvc", "evc", "generic", "color", "io"
    ])
    # Add version-like suffixes sometimes
    if rng.random() < 0.5:
        core += f"-{rng.randint(0, 5)}.{rng.randint(0, 9)}"
    if rng.random() < 0.4:
        core += "-debug" if rng.random() < 0.5 else "-release"
    # sprinkle unicode sometimes
    if rng.random() < 0.3:
        core += "-" + _random_unicode_fragment(rng)

    base = prefix + core
    # Choose extension by platform tendency, but mix
    if os.name == "nt":
        exts = PLUGIN_EXTS_WIN + PLUGIN_EXTS_POSIX
    else:
        exts = PLUGIN_EXTS_POSIX + PLUGIN_EXTS_WIN
    ext = _rand_choice(rng, exts)
    return base + ext


def _rand_regular_filename(rng: random.Random) -> str:
    name_core = _rand_choice(rng, [
        "image", "sample", "test", "input", "data", "pic", "thumb", "primary"
    ])
    # add numeric or hex suffix
    if rng.random() < 0.8:
        if rng.random() < 0.5:
            name_core += f"_{rng.randint(0, 9999)}"
        else:
            name_core += f"_{rng.randrange(0, 1<<24):06x}"
    if rng.random() < 0.35:
        name_core += "-" + _random_unicode_fragment(rng)

    # choose extension
    ext = _rand_choice(rng, GENERIC_FILE_EXTS)
    return name_core + ext


def _rand_dir_path(rng: random.Random) -> str:
    parts = []
    # start from a safe base or absolute
    mode = rng.random()
    if mode < 0.25:
        parts.append(_rand_choice(rng, SAFE_DIRS))
    elif mode < 0.5:
        # absolute root
        parts.append(SEP)
    elif mode < 0.75:
        parts.append(_rand_choice(rng, EDGE_DIRS))
    else:
        parts.append(".")

    # add 0-3 subdirs
    for _ in range(rng.randint(0, 3)):
        sub = _rand_choice(rng, [
            "plugins", "load", "lib", "bin", "share", "heif", "avif", "extra",
            _random_unicode_fragment(rng)
        ])
        parts.append(sub)

    # Join carefully: if first is absolute root, avoid double separators
    if parts and parts[0] == SEP:
        path = SEP
        if len(parts) > 1:
            path += SEP.join(p for p in parts[1:] if p and p != SEP)
    else:
        path = SEP.join(p for p in parts if p)
    return path


def _maybe_make_dir_like(rng: random.Random, path: str) -> str:
    # Sometimes return a directory path; other times append a filename
    if rng.random() < 0.5:
        return path
    # Append a plausible plugin basename or file name
    leaf = _rand_choice(rng, [
        _rand_plugin_basename(rng), _rand_regular_filename(rng), _rand_choice(rng, EDGE_NAMES)
    ])
    if not path or path.endswith(SEP):
        return path + leaf
    else:
        return path + SEP + leaf


def _mutate_with_edges(rng: random.Random, s: str) -> str:
    # Add edge-case elements: trailing slashes, spaces, dots, device-like names (harmless strings)
    if rng.random() < 0.2:
        s += SEP
    if rng.random() < 0.2:
        s = s + (" " * rng.randint(1, 3))
    if rng.random() < 0.1:
        s = s + "."
    if rng.random() < 0.15:
        s = s.replace("/./", "/")
    if rng.random() < 0.15:
        s = s.replace("//", "/")
    return s


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Select a strategy for the path kind
    strategy = rng.random()

    if strategy < 0.2:
        # Pure directory path (existing or plausible)
        path = _rand_dir_path(rng)
        path = _mutate_with_edges(rng, path)
    elif strategy < 0.45:
        # Directory plus plugin-like filename
        base = _rand_dir_path(rng)
        path = _maybe_make_dir_like(rng, base)
        path = _mutate_with_edges(rng, path)
    elif strategy < 0.7:
        # Relative simple filename for reading/writing HEIF
        path = _rand_regular_filename(rng)
        path = _mutate_with_edges(rng, path)
    else:
        # Absolute path with nested directories and unicode
        base = _rand_dir_path(rng)
        # ensure absolute on this branch
        if not base.startswith(SEP):
            base = SEP + base.lstrip(SEP)
        # add 1-2 unicode dirs
        for _ in range(rng.randint(1, 2)):
            base = base.rstrip(SEP) + SEP + _random_unicode_fragment(rng)
        # choose leaf
        leaf = _rand_choice(rng, [_rand_plugin_basename(rng), _rand_regular_filename(rng)])
        path = base.rstrip(SEP) + SEP + leaf
        path = _mutate_with_edges(rng, path)

    # Clamp to max size and ensure not empty
    if not path:
        path = "."

    # Encode as UTF-8, append NUL terminator for C-string expectations
    data = path.encode('utf-8', errors='ignore')[:4095]
    if not data:
        data = b"."
    if len(data) < 4096:
        data += b"\x00"
    else:
        # ensure last byte NUL if truncated to limit
        data = data[:-1] + b"\x00"

    return data

