]

QUERY_KEYS = [
    "v", "id", "lang", "charset", "encoding", "rev",
]


def _rand_choice(rng: random.Random, arr: List[str]) -> str:
    return arr[rng.randrange(len(arr))]


def _rand_token(rng: random.Random, min_len=1, max_len=12, alphabet=string.ascii_letters + string.digits + "-_.") -> str:
    n = rng.randint(min_len, max_len)
    return ''.join(rng.choice(alphabet) for _ in range(n))


def _gen_http_uri(rng: random.Random) -> str:
    scheme = _rand_choice(rng, ["http", "https"])  # widely accepted absolute URIs
    host = _rand_choice(rng, HOSTS)
    # Optionally add subdomains
    if rng.random() < 0.4:
        sub = _rand_token(rng, 2, 8).lower()
        host = f"{sub}.{host}"
    # Optional port
    if rng.random() < 0.25:
        port = rng.choice([80, 443, 8080, 8443, rng.randint(1024, 65535)])
        host = f"{host}:{port}"
    # Build path
    segs = []
    for _ in range(rng.randint(0, 4)):
        segs.append(_rand_choice(rng, PATH_SEGMENTS))
    if rng.random() < 0.5:
        # Mix with random tokens
        for _ in range(rng.randint(0, 2)):
            segs.append(_rand_token(rng, 1, 10))
    path = "/" + "/".join(segs) if segs else ""
    # Optional query
    query = ""
    if rng.random() < 0.5:
        pairs = []
        for _ in range(rng.randint(1, 3)):
            k = _rand_choice(rng, QUERY_KEYS)
            v = _rand_token(rng, 1, 8)
            pairs.append(f"{k}={v}")
        query = "?" + "&".join(pairs)
    # Optional fragment
    frag = ""
    if rng.random() < 0.3:
        frag = "#" + _rand_token(rng, 1, 8)
    return f"{scheme}://{host}{path}{query}{frag}"


def _gen_urn_uri(rng: random.Random) -> str:
    nid = _rand_choice(rng, URN_NAMESPACES)
    if nid == "uuid":
        # RFC4122 format
        hexs = [rng.getrandbits(32), rng.getrandbits(16), rng.getrandbits(16), rng.getrandbits(16), rng.getrandbits(48)]
        uuid = f"{hexs[0]:08x}-{hexs[1]:04x}-{hexs[2] & 0x0fff | 0x4000:04x}-{hexs[3] & 0x3fff | 0x8000:04x}-{hexs[4]:012x}"
        return f"urn:uuid:{uuid}"
    # Generic namespace-specific string
    nss_parts = []
    for _ in range(rng.randint(1, 4)):
        nss_parts.append(_rand_token(rng, 1, 10, alphabet=string.ascii_lowercase + string.digits + "-._+"))
    return f"urn:{nid}:{':'.join(nss_parts)}"


def _gen_data_uri(rng: random.Random) -> str:
    med = _rand_choice(rng, MEDIATYPES)
    # Optional parameters
    params = []
    if rng.random() < 0.5:
        params.append("charset=UTF-8")
    if rng.random() < 0.3:
        params.append("profile=heif")
    pstr = (";" + ";".join(params)) if params else ""
    # Choose between base64 and percent-encoded; keep it short to fit <=128
    if rng.random() < 0.6:
        alphabet = string.ascii_letters + string.digits + "+/="
        payload = ''.join(rng.choice(alphabet) for _ in range(rng.randint(8, 24)))
        return f"data:{med}{pstr};base64,{payload}"
    else:
        # url-encoded short text
        txt = _rand_choice(rng, ["heif", "metadata", "type", "nclx", "xmp"]) + _rand_token(rng, 0, 6)
        enc = ''.join(c if c.isalnum() else f"%{ord(c):02X}" for c in txt)
        return f"data:{med}{pstr},{enc}"


def gen_absolute_uri(rng: random.Random) -> str:
    kind = rng.random()
    if kind < 0.5:
        return _gen_http_uri(rng)
    elif kind < 0.8:
        return _gen_urn_uri(rng)
    else:
        return _gen_data_uri(rng)


def gen_payload(rng: random.Random) -> bytes:
    # Generate diverse payloads up to 1024 bytes.
    choice = rng.random()
    if choice < 0.25:
        # Small textual payload
        lines = []
        for _ in range(rng.randint(1, 5)):
            k = _rand_token(rng, 3, 10)
            v = _rand_token(rng, 0, 12)
            lines.append(f"{k}:{v}")
        return ("\n".join(lines)).encode("utf-8")
    elif choice < 0.5:
        # JSON-like metadata
        keys = ["type", "version", "note", "id", "lang"]
        obj = {rng.choice(keys): _rand_token(rng, 3, 10) for _ in range(rng.randint(2, 4))}
        # ensure deterministic ordering by sorting keys
        items = ",".join(f'"{k}":"{obj[k]}"' for k in sorted(obj.keys()))
        return ("{" + items + "}").encode("utf-8")
    elif choice < 0.75:
        # Binary-looking payload
        size = rng.randint(0, 256)
        return bytes(rng.getrandbits(8) for _ in range(size))
    else:
        # Repeated pattern to reach larger sizes but <= 1024
        unit = _rand_token(rng, 4, 16).encode("ascii")
        reps = max(1, rng.randint(1, 1024 // max(1, len(unit))))
        data = (unit * reps)[: rng.randint(0, 1024)]
        return data


def pack_two_c_strings(s1: bytes, s2: bytes, max_total: int = 4096) -> bytes:
    # Ensure NUL-terminated byte strings and combined size limit
    s1 = s1.replace(b"\x00", b"")
    s2 = s2.replace(b"\x00", b"")
    # Reserve two NULs
    limit = max_total - 2
    # Trim to limit while keeping s1 and s2 non-negative
    half = limit // 2
    if len(s1) > half:
        s1 = s1[:half]
    if len(s2) > limit - len(s1):
        s2 = s2[: limit - len(s1)]
    return s1 + b"\x00" + s2 + b"\x00"


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Create a valid absolute URI limited to 128 bytes (stub trims to 128)
    # We enforce limit here to stay valid and predictable.
    for _ in range(10):
        uri = gen_absolute_uri(rng)
        if len(uri.encode('utf-8')) <= 128:
            break
    uri_b = uri.encode('utf-8')[:128]

    payload = gen_payload(rng)[:1024]

    buf = pack_two_c_strings(uri_b, payload, max_total=4096)
    return buf
